-- H2-compatible version of V10 for local dev.
--
-- The Postgres variant (db/vendor/postgresql/V10__add_highlights.sql) adds
-- a pgvector `embedding` column plus an HNSW ANN index. H2 has neither, so
-- this version creates just the row columns that the JPA entity maps; the
-- embedding column is intentionally omitted — semantic search over
-- highlights won't work in dev, but the rest of the app boots fine.

CREATE TABLE highlights (
    id           BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id      BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    book_id      BIGINT       NOT NULL REFERENCES books(id) ON DELETE CASCADE,
    text         TEXT         NOT NULL,
    note         TEXT,
    page_number  INTEGER,
    created_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_highlights_user_id ON highlights(user_id);
CREATE INDEX idx_highlights_book_id ON highlights(book_id);
